<?php
require_once 'config.php'; header('Content-Type: application/json; charset=utf-8'); if(empty($_SESSION['admin_id'])){http_response_code(401);echo json_encode(['ok'=>false,'message'=>'Sesi admin berakhir. Silakan login ulang.']);exit;}
try{$pdo=db();$action=$_GET['action']??'';if($action==='save_sale'&&$_SERVER['REQUEST_METHOD']==='POST'){$d=json_decode(file_get_contents('php://input'),true);if(!is_array($d)||!isset($d['t'],$d['total'],$d['items'])||!is_array($d['items'])){http_response_code(400);echo json_encode(['ok'=>false,'message'=>'Data transaksi tidak valid']);exit;}$key=hash('sha256',session_id().'|'.($d['t']).'|'.($d['meja']??''). '|'.($d['name']??''));$dt=(new DateTime('@'.intdiv((int)$d['t'],1000)))->setTimezone(new DateTimeZone(date_default_timezone_get()))->format('Y-m-d H:i:s');$type=($d['meja']??'')==='TAKEAWAY'?'takeaway':'dine-in';$st=$pdo->prepare('INSERT IGNORE INTO sales(client_key,sale_time,order_type,customer_name,subtotal,discount,discount_code,total,items_json) VALUES(?,?,?,?,?,?,?,?,?)');$st->execute([$key,$dt,$type,mb_substr(trim((string)($d['name']??'Pelanggan')),0,120),max(0,(int)($d['sub']??$d['total'])),max(0,(int)($d['disc']??0)),mb_substr((string)($d['code']??''),0,40),max(0,(int)$d['total']),json_encode($d['items'],JSON_UNESCAPED_UNICODE)]);echo json_encode(['ok'=>true]);exit;}if($action==='sales'){$st=$pdo->query('SELECT sale_time,order_type,customer_name,subtotal,discount,discount_code,total,items_json FROM sales ORDER BY sale_time DESC LIMIT 2000');$sales=[];foreach($st as $r){$sales[]=['t'=>strtotime($r['sale_time'])*1000,'meja'=>$r['order_type']==='takeaway'?'TAKEAWAY':'Database','name'=>$r['customer_name'],'sub'=>(int)$r['subtotal'],'disc'=>(int)$r['discount'],'code'=>$r['discount_code'],'total'=>(int)$r['total'],'items'=>json_decode($r['items_json'],true)?:[]];}echo json_encode(['ok'=>true,'sales'=>array_reverse($sales)]);exit;}http_response_code(404);echo json_encode(['ok'=>false,'message'=>'Endpoint tidak ditemukan']);}catch(Throwable $e){http_response_code(500);echo json_encode(['ok'=>false,'message'=>'Kesalahan database. Periksa konfigurasi MySQL dan impor database.sql.']);}
?>